// Public type contract for the git-core engine.
//
// The individual type files under ./generated are produced from the Rust
// structs in the git-core crate via ts-rs (see the crate's `typegen` feature).
// Do not edit ./generated by hand — run `pnpm typegen` from the repo root.
//
// This barrel is the only entry point consumers should import from:
//   import type { GitLogEntry, GitDiffContentResult } from "@surdy/git-core-types";

export type { GitRepoInfo } from "./generated/GitRepoInfo";
export type { GitChangedFile } from "./generated/GitChangedFile";
export type { GitStatusSnapshot } from "./generated/GitStatusSnapshot";
export type { GitPanelSnapshot } from "./generated/GitPanelSnapshot";
export type { DiscardEntry } from "./generated/DiscardEntry";
export type { GitDiffResult } from "./generated/GitDiffResult";
export type { GitDiffContentResult } from "./generated/GitDiffContentResult";
export type { GitCommitResult } from "./generated/GitCommitResult";
export type { GitCommitFileChange } from "./generated/GitCommitFileChange";
export type { GitLogEntry } from "./generated/GitLogEntry";
export type { GitPushResult } from "./generated/GitPushResult";

/** Minimum git version supported by the git-core engine. Mirrors the Rust `MIN_GIT_VERSION`. */
export const MIN_GIT_VERSION = "2.23";
